using SmartiePaws.Inventory.Core.Entities.Catalog;
using SmartiePaws.Inventory.Core.Enums.Sales;

namespace SmartiePaws.Inventory.Core.Entities.Sales;

/// <summary>
/// One row per item sold within a <see cref="Sale"/> -- the equivalent of a single line on a
/// paper receipt. Immutable once written, with no independent timestamps of its own -- it's a
/// detail row of its parent Sale, not a standalone lifecycle.
/// </summary>
public class SaleLineItem
{
  /// <summary>
  /// Primary key. Generated by Postgres (<c>gen_random_uuid()</c>) on insert.
  /// </summary>
  public Guid Id { get; set; }

  /// <summary>
  /// Foreign key to the Sale this line belongs to.
  /// </summary>
  public Guid SaleId { get; set; }

  /// <summary>
  /// Navigation to the Sale. Only populated when explicitly requested.
  /// </summary>
  public Sale Sale { get; set; } = null!;

  /// <summary>
  /// Foreign key to what was actually sold on this line.
  /// </summary>
  public Guid ProductVariantId { get; set; }

  /// <summary>
  /// Navigation to the variant sold. Only populated when explicitly requested.
  /// </summary>
  public ProductVariant ProductVariant { get; set; } = null!;

  /// <summary>
  /// How many units of that variant were sold.
  /// </summary>
  public int Quantity { get; set; }

  /// <summary>
  /// The price actually charged per unit on this sale -- may differ from
  /// <see cref="ProductVariant.Price"/> if this specific line was discounted or sold at a
  /// one-off price.
  /// </summary>
  public decimal UnitPrice { get; set; }

  /// <summary>
  /// Same shape as the sale-level discount fields, but scoped to just this one line (e.g. "this
  /// particular item is 20% off" rather than the whole sale). Nullable -- not every line has a
  /// line-level discount.
  /// </summary>
  public DiscountType? LineDiscountType { get; set; }

  /// <summary>
  /// The raw discount number paired with <see cref="LineDiscountType"/>.
  /// </summary>
  public decimal? LineDiscountValue { get; set; }

  /// <summary>
  /// The actual dollar amount this line's discount resolves to, computed once and stored.
  /// </summary>
  public decimal? LineDiscountAmount { get; set; }

  /// <summary>
  /// Quantity x UnitPrice, minus LineDiscountAmount.
  /// </summary>
  public decimal LineTotal { get; set; }

  /// <summary>
  /// The FIFO cost of the units sold on this line, captured at the moment of sale. If the
  /// quantity was drawn from more than one lot (see <see cref="SaleLineItemLotConsumption"/>),
  /// this is the blended average across them. Stored as a snapshot so profit-margin reporting
  /// stays accurate even though a lot's cost never changes after the fact -- this is what
  /// actually makes a profit dashboard possible.
  /// </summary>
  public decimal UnitCostAtSale { get; set; }
}
